package gitrepo

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/testutil/gitenv"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/stretchr/testify/require"
)

func TestCompareAndSwapRef_RejectsSymbolicRef(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name string
		init func(*testing.T) (repoDir, initial, replacement string)
	}{
		{
			name: "files",
			init: func(t *testing.T) (string, string, string) {
				t.Helper()
				repoDir := t.TempDir()
				gitenv.Run(t, repoDir, "init", "-b", "main")
				gitenv.Run(t, repoDir, "config", "user.name", "Test User")
				gitenv.Run(t, repoDir, "config", "user.email", "test@example.com")
				gitenv.Run(t, repoDir, "config", "commit.gpgsign", "false")
				require.NoError(t, os.WriteFile(filepath.Join(repoDir, "initial.txt"), []byte("initial\n"), 0o644))
				gitenv.Run(t, repoDir, "add", "initial.txt")
				gitenv.Run(t, repoDir, "commit", "--no-gpg-sign", "-m", "initial")
				initial := strings.TrimSpace(gitenv.Run(t, repoDir, "rev-parse", "HEAD"))
				require.NoError(t, os.WriteFile(filepath.Join(repoDir, "next.txt"), []byte("next\n"), 0o644))
				gitenv.Run(t, repoDir, "add", "next.txt")
				gitenv.Run(t, repoDir, "commit", "--no-gpg-sign", "-m", "next")
				replacement := strings.TrimSpace(gitenv.Run(t, repoDir, "rev-parse", "HEAD"))
				return repoDir, initial, replacement
			},
		},
		{
			name: "reftable",
			init: func(t *testing.T) (string, string, string) {
				t.Helper()
				repoDir, initial := initReftableRepo(t, "initial.txt", "initial\n")
				replacement := reftableCommit(t, repoDir, "next.txt", "next\n")
				return repoDir, initial, replacement
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			repoDir, initial, replacement := tt.init(t)
			refName := plumbing.ReferenceName("refs/entire/symbolic-cas")
			targetName := plumbing.NewBranchReferenceName("main")
			gitenv.Run(t, repoDir, "update-ref", targetName.String(), initial)
			gitenv.Run(t, repoDir, "symbolic-ref", refName.String(), targetName.String())

			err := CompareAndSwapRef(
				context.Background(),
				repoDir,
				refName,
				plumbing.NewHash(replacement),
				plumbing.NewHash(initial),
			)

			require.ErrorIs(t, err, ErrRefSymbolic)
			require.Equal(t, targetName.String(), strings.TrimSpace(gitenv.Run(t, repoDir, "symbolic-ref", refName.String())))
			require.Equal(t, initial, strings.TrimSpace(gitenv.Run(t, repoDir, "rev-parse", targetName.String())))

			gitenv.Run(t, repoDir, "symbolic-ref", "-d", refName.String())
			gitenv.Run(t, repoDir, "update-ref", refName.String(), initial)
			err = CompareAndSwapRef(
				context.Background(),
				repoDir,
				refName,
				plumbing.NewHash(replacement),
				plumbing.NewHash(initial),
			)
			require.NoError(t, err)
			require.Equal(t, replacement, strings.TrimSpace(gitenv.Run(t, repoDir, "rev-parse", refName.String())))
		})
	}
}

func TestCompareAndSwapRef_ReftableLockContention(t *testing.T) {
	t.Parallel()
	repoDir, initial := initReftableRepo(t, "initial.txt", "initial\n")
	newHash := reftableCommit(t, repoDir, "next.txt", "next\n")
	refName := plumbing.ReferenceName("refs/entire/reftable-lock")
	gitenv.Run(t, repoDir, "update-ref", refName.String(), initial)
	require.NoError(t, os.WriteFile(filepath.Join(repoDir, ".git", "reftable", "tables.list.lock"), nil, 0o600))

	err := CompareAndSwapRef(
		context.Background(),
		repoDir,
		refName,
		plumbing.NewHash(newHash),
		plumbing.NewHash(initial),
	)

	require.ErrorIs(t, err, ErrRefLocked)
	require.Equal(t, initial, strings.TrimSpace(gitenv.Run(t, repoDir, "rev-parse", refName.String())))
}

func TestRefCASErrorClassification(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name         string
		stderr       string
		wantConflict bool
		wantLocked   bool
	}{
		{
			name:         "expected value mismatch",
			stderr:       "cannot lock ref 'refs/heads/main': is at aaaa but expected bbbb",
			wantConflict: true,
		},
		{
			name:         "expected ref was deleted",
			stderr:       "cannot lock ref 'refs/heads/main': unable to resolve reference 'refs/heads/main'",
			wantConflict: true,
		},
		{
			name:         "create if absent conflict",
			stderr:       "cannot lock ref 'refs/heads/main': reference already exists",
			wantConflict: true,
		},
		{
			name:       "lock held by another process",
			stderr:     "unable to create '/repo/.git/refs/heads/main.lock': File exists.",
			wantLocked: true,
		},
		{
			name:       "reftable lock held by another process",
			stderr:     "fatal: update_ref failed for ref 'refs/heads/main': cannot lock references",
			wantLocked: true,
		},
		{
			name:   "permission failure",
			stderr: "cannot lock ref 'refs/heads/main': unable to create '/repo/.git/refs/heads/main.lock': Permission denied",
		},
		{
			name:   "namespace conflict",
			stderr: "cannot lock ref 'refs/heads/main/child': 'refs/heads/main' exists; cannot create 'refs/heads/main/child'",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			stderr := []byte(tt.stderr)
			require.Equal(t, tt.wantConflict, isRefCASConflict(stderr))
			require.Equal(t, tt.wantLocked, isRefLockContention(stderr))
		})
	}
}
package gitrepo

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os/exec"
	"strings"

	"github.com/go-git/go-git/v6/plumbing"
)

var (
	// ErrRefCASConflict means the ref no longer has the expected old value.
	ErrRefCASConflict = errors.New("git reference changed during compare-and-swap")
	// ErrRefLocked means native Git could not acquire the ref lock.
	ErrRefLocked = errors.New("git reference lock is unavailable")
	// ErrRefSymbolic means the requested CAS target is a symbolic reference.
	ErrRefSymbolic = errors.New("git reference is symbolic")
)

// CompareAndSwapRef updates refName through native Git without dereferencing a
// symbolic ref. ZeroHash as expectedHash requires that refName does not exist.
func CompareAndSwapRef(
	ctx context.Context,
	repoRoot string,
	refName plumbing.ReferenceName,
	newHash, expectedHash plumbing.Hash,
) error {
	tx, err := prepareRefCAS(ctx, repoRoot, refName, newHash, expectedHash)
	if err != nil {
		return err
	}
	defer func() { _ = tx.abort() }()

	target, symbolic, err := symbolicRefTarget(ctx, repoRoot, refName)
	if err != nil {
		return errors.Join(err, tx.abort())
	}
	if symbolic {
		return errors.Join(
			fmt.Errorf("ref %s points to %s: %w", refName, target, ErrRefSymbolic),
			tx.abort(),
		)
	}
	return tx.commit()
}

type refCASTransaction struct {
	ctx     context.Context
	refName plumbing.ReferenceName
	cmd     *exec.Cmd
	stdin   io.WriteCloser
	stdout  *bufio.Scanner
	stderr  bytes.Buffer
	done    bool
}

func prepareRefCAS(
	ctx context.Context,
	repoRoot string,
	refName plumbing.ReferenceName,
	newHash, expectedHash plumbing.Hash,
) (*refCASTransaction, error) {
	if err := refName.Validate(); err != nil {
		return nil, fmt.Errorf("validate ref for compare-and-swap: %w", err)
	}
	oldValue := strings.Repeat("0", newHash.HexSize())
	if expectedHash != plumbing.ZeroHash {
		oldValue = expectedHash.String()
	}

	cmd := exec.CommandContext(ctx, "git", "update-ref", "--stdin")
	cmd.Dir = repoRoot
	cmd.Env = gitPlumbingEnv()
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return nil, fmt.Errorf("open git update-ref stdin: %w", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		_ = stdin.Close()
		return nil, fmt.Errorf("open git update-ref stdout: %w", err)
	}
	tx := &refCASTransaction{
		ctx:     ctx,
		refName: refName,
		cmd:     cmd,
		stdin:   stdin,
		stdout:  bufio.NewScanner(stdout),
	}
	cmd.Stderr = &tx.stderr
	if err := cmd.Start(); err != nil {
		_ = stdin.Close()
		return nil, fmt.Errorf("start git update-ref transaction for %s: %w", refName, err)
	}

	commands := []struct {
		request  string
		response string
	}{
		{request: "start", response: "start: ok"},
		{request: "option no-deref"},
		{request: fmt.Sprintf("update %s %s %s", refName, newHash, oldValue)},
		{request: "prepare", response: "prepare: ok"},
	}
	for _, command := range commands {
		if err := tx.exchange(command.request, command.response); err != nil {
			return nil, tx.preparationError(err)
		}
	}
	return tx, nil
}

func (tx *refCASTransaction) exchange(request, response string) error {
	if _, err := fmt.Fprintln(tx.stdin, request); err != nil {
		return fmt.Errorf("write %q: %w", request, err)
	}
	if response == "" {
		return nil
	}
	if !tx.stdout.Scan() {
		if err := tx.stdout.Err(); err != nil {
			return fmt.Errorf("read response to %q: %w", request, err)
		}
		return fmt.Errorf("read response to %q: %w", request, io.ErrUnexpectedEOF)
	}
	if got := tx.stdout.Text(); got != response {
		return fmt.Errorf("response to %q was %q, want %q", request, got, response)
	}
	return nil
}

func (tx *refCASTransaction) preparationError(protocolErr error) error {
	waitErr := tx.wait()
	if waitErr != nil {
		return classifyRefCASError(tx.ctx, tx.refName, tx.stderr.Bytes(), waitErr)
	}
	return fmt.Errorf("prepare git update-ref transaction for %s: %w", tx.refName, protocolErr)
}

func (tx *refCASTransaction) commit() error {
	return tx.finish("commit", "commit: ok")
}

func (tx *refCASTransaction) abort() error {
	if tx.done {
		return nil
	}
	return tx.finish("abort", "abort: ok")
}

func (tx *refCASTransaction) finish(request, response string) error {
	protocolErr := tx.exchange(request, response)
	waitErr := tx.wait()
	if waitErr != nil {
		return classifyRefCASError(tx.ctx, tx.refName, tx.stderr.Bytes(), waitErr)
	}
	if protocolErr != nil {
		return fmt.Errorf("finish git update-ref transaction for %s: %w", tx.refName, protocolErr)
	}
	return nil
}

func (tx *refCASTransaction) wait() error {
	if tx.done {
		return nil
	}
	tx.done = true
	_ = tx.stdin.Close()
	return tx.cmd.Wait()
}

func classifyRefCASError(ctx context.Context, refName plumbing.ReferenceName, stderr []byte, err error) error {
	if ctxErr := ctx.Err(); ctxErr != nil {
		return fmt.Errorf("git update-ref %s: %w", refName, ctxErr)
	}
	detail := strings.TrimSpace(string(stderr))
	switch {
	case isRefCASConflict(stderr):
		return fmt.Errorf("git update-ref %s: %s: %w", refName, detail, ErrRefCASConflict)
	case isRefLockContention(stderr):
		return fmt.Errorf("git update-ref %s: %s: %w", refName, detail, ErrRefLocked)
	default:
		return fmt.Errorf("git update-ref %s: %s: %w", refName, detail, err)
	}
}

func symbolicRefTarget(ctx context.Context, repoRoot string, refName plumbing.ReferenceName) (string, bool, error) {
	cmd := exec.CommandContext(ctx, "git", "symbolic-ref", "-q", "--end-of-options", refName.String())
	cmd.Dir = repoRoot
	cmd.Env = gitPlumbingEnv()
	target, err := cmd.Output()
	if err == nil {
		return strings.TrimSpace(string(target)), true, nil
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		return "", false, fmt.Errorf("probe symbolic ref %s: %w", refName, ctxErr)
	}
	var exitErr *exec.ExitError
	var stderr []byte
	if errors.As(err, &exitErr) {
		stderr = exitErr.Stderr
		if refLookupAbsent(err, stderr) {
			return "", false, nil
		}
	}
	detail := strings.TrimSpace(string(stderr))
	if detail == "" {
		return "", false, fmt.Errorf("probe symbolic ref %s: %w", refName, err)
	}
	return "", false, fmt.Errorf("probe symbolic ref %s: %s: %w", refName, detail, err)
}

// isRefCASConflict reports that git rejected the expected old value, including
// the cases where a required ref disappeared or a create-only ref appeared.
func isRefCASConflict(stderr []byte) bool {
	msg := strings.ToLower(string(stderr))
	return strings.Contains(msg, "but expected") ||
		strings.Contains(msg, "unable to resolve reference") ||
		strings.Contains(msg, "reference already exists")
}

func isRefLockContention(stderr []byte) bool {
	msg := strings.ToLower(string(stderr))
	return strings.Contains(msg, "cannot lock references") ||
		strings.Contains(msg, ".lock") && strings.Contains(msg, "file exists")
}

