   24	
   25	// CompareAndSwapRef atomically updates a direct ref through native Git and
   26	// rejects symbolic refs. ZeroHash as expectedHash requires that refName does
   27	// not exist.
   28	func CompareAndSwapRef(
   29		ctx context.Context,
   30		repoRoot string,
   31		refName plumbing.ReferenceName,
   32		newHash, expectedHash plumbing.Hash,
   33	) error {
   34		tx, err := prepareRefCAS(ctx, repoRoot, refName, newHash, expectedHash)
   35		if err != nil {
   36			return err
   37		}
   38	
   39		target, symbolic, err := symbolicRefTarget(ctx, repoRoot, refName)
   40		if err != nil {
   41			return errors.Join(err, tx.abort())
   42		}
