   44			return errors.Join(
   45				fmt.Errorf("ref %s points to %s: %w", refName, target, ErrRefSymbolic),
   46				tx.abort(),
   47			)
   48		}
   49		return tx.commit()
   50	}
   51	
   52	type refCASTransaction struct {
   53		ctx     context.Context
