   68		if err := refName.Validate(); err != nil {
   69			return nil, fmt.Errorf("validate ref for compare-and-swap: %w", err)
   70		}
   71		oldValue := strings.Repeat("0", newHash.HexSize())
   72		if expectedHash != plumbing.ZeroHash {
