  118	func (tx *refCASTransaction) exchange(request, response string) error {
  119		if _, err := fmt.Fprintln(tx.stdin, request); err != nil {
  120			return fmt.Errorf("write %q: %w", request, err)
  121		}
  122		if response == "" {
  123			return nil
  124		}
  125		if !tx.stdout.Scan() {
  126			if err := tx.stdout.Err(); err != nil {
  127				return fmt.Errorf("read response to %q: %w", request, err)
  128			}
  129			return fmt.Errorf("read response to %q: %w", request, io.ErrUnexpectedEOF)
  130		}
  131		if got := tx.stdout.Text(); got != response {
  132			return fmt.Errorf("response to %q was %q, want %q", request, got, response)
  133		}
  134		return nil
  135	}
  136	
  137	func (tx *refCASTransaction) preparationError(protocolErr error) error {
