   52	type refCASTransaction struct {
   53		ctx     context.Context
   54		refName plumbing.ReferenceName
   55		cmd     *exec.Cmd
   56		stdin   io.WriteCloser
   57		stdout  *bufio.Scanner
   58		stderr  bytes.Buffer
   59		done    bool
   60	}
   61	
   62	func prepareRefCAS(
   63		ctx context.Context,
   64		repoRoot string,
   65		refName plumbing.ReferenceName,
   66		newHash, expectedHash plumbing.Hash,
   67	) (*refCASTransaction, error) {
   68		if err := refName.Validate(); err != nil {
   69			return nil, fmt.Errorf("validate ref for compare-and-swap: %w", err)
   70		}
   71		oldValue := strings.Repeat("0", newHash.HexSize())
   72		if expectedHash != plumbing.ZeroHash {
   73			oldValue = expectedHash.String()
   74		}
   75	
   76		cmd := exec.CommandContext(ctx, "git", "update-ref", "--stdin")
   77		cmd.Dir = repoRoot
   78		cmd.Env = gitPlumbingEnv()
   79		stdin, err := cmd.StdinPipe()
   80		if err != nil {
   81			return nil, fmt.Errorf("open git update-ref stdin: %w", err)
   82		}
   83		stdout, err := cmd.StdoutPipe()
   84		if err != nil {
   85			_ = stdin.Close()
   86			return nil, fmt.Errorf("open git update-ref stdout: %w", err)
   87		}
   88		tx := &refCASTransaction{
   89			ctx:     ctx,
   90			refName: refName,
   91			cmd:     cmd,
   92			stdin:   stdin,
   93			stdout:  bufio.NewScanner(stdout),
   94		}
   95		cmd.Stderr = &tx.stderr
   96		if err := cmd.Start(); err != nil {
   97			_ = stdin.Close()
   98			return nil, fmt.Errorf("start git update-ref transaction for %s: %w", refName, err)
   99		}
  100	
  101		commands := []struct {
  102			request  string
  103			response string
  104		}{
  105			{request: "start", response: "start: ok"},
  106			{request: "option no-deref"},
  107			{request: fmt.Sprintf("update %s %s %s", refName, newHash, oldValue)},
  108			{request: "prepare", response: "prepare: ok"},
  109		}
  110		for _, command := range commands {
  111			if err := tx.exchange(command.request, command.response); err != nil {
  112				return nil, tx.preparationError(err)
  113			}
  114		}
  115		return tx, nil
  116	}
  117	
  118	func (tx *refCASTransaction) exchange(request, response string) error {
  119		if _, err := fmt.Fprintln(tx.stdin, request); err != nil {
  120			return fmt.Errorf("write %q: %w", request, err)
  121		}
  122		if response == "" {
  123			return nil
  124		}
  125		if !tx.stdout.Scan() {
  126			if err := tx.stdout.Err(); err != nil {
  127				return fmt.Errorf("read response to %q: %w", request, err)
  128			}
  129			return fmt.Errorf("read response to %q: %w", request, io.ErrUnexpectedEOF)
  130		}
  131		if got := tx.stdout.Text(); got != response {
  132			return fmt.Errorf("response to %q was %q, want %q", request, got, response)
  133		}
  134		return nil
  135	}
  136	
  137	func (tx *refCASTransaction) preparationError(protocolErr error) error {
  138		waitErr := tx.wait()
  139		if waitErr != nil {
  140			return classifyRefCASError(tx.ctx, tx.refName, tx.stderr.Bytes(), waitErr)
  141		}
  142		return fmt.Errorf("prepare git update-ref transaction for %s: %w", tx.refName, protocolErr)
  143	}
  144	
  145	func (tx *refCASTransaction) commit() error {
  146		return tx.finish("commit", "commit: ok")
  147	}
  148	
  149	func (tx *refCASTransaction) abort() error {
  150		if tx.done {
  151			return nil
  152		}
  153		return tx.finish("abort", "abort: ok")
  154	}
  155	
  156	func (tx *refCASTransaction) finish(request, response string) error {
  157		protocolErr := tx.exchange(request, response)
  158		waitErr := tx.wait()
  159		if waitErr != nil {
  160			return classifyRefCASError(tx.ctx, tx.refName, tx.stderr.Bytes(), waitErr)
  161		}
  162		if protocolErr != nil {
  163			return fmt.Errorf("finish git update-ref transaction for %s: %w", tx.refName, protocolErr)
  164		}
  165		return nil
  166	}
  167	
  168	func (tx *refCASTransaction) wait() error {
  169		if tx.done {
  170			return nil
  171		}
  172		tx.done = true
  173		_ = tx.stdin.Close()
  174		if err := tx.cmd.Wait(); err != nil {
  175			return fmt.Errorf("wait for git update-ref transaction: %w", err)
  176		}
  177		return nil
  178	}
