  180	func classifyRefCASError(ctx context.Context, refName plumbing.ReferenceName, stderr []byte, err error) error {
  181		if ctxErr := ctx.Err(); ctxErr != nil {
  182			return fmt.Errorf("git update-ref %s: %w", refName, ctxErr)
  183		}
  184		detail := strings.TrimSpace(string(stderr))
  185		switch {
  186		case isRefCASConflict(stderr):
  187			return fmt.Errorf("git update-ref %s: %s: %w", refName, detail, ErrRefCASConflict)
  188		case isRefLockContention(stderr):
  189			return fmt.Errorf("git update-ref %s: %s: %w", refName, detail, ErrRefLocked)
  190		default:
  191			return fmt.Errorf("git update-ref %s: %s: %w", refName, detail, err)
  192		}
  193	}
