  195	func symbolicRefTarget(ctx context.Context, repoRoot string, refName plumbing.ReferenceName) (string, bool, error) {
  196		cmd := exec.CommandContext(ctx, "git", "symbolic-ref", "-q", "--end-of-options", refName.String())
  197		cmd.Dir = repoRoot
  198		cmd.Env = gitPlumbingEnv()
  199		target, err := cmd.Output()
  200		if err == nil {
  201			return strings.TrimSpace(string(target)), true, nil
  202		}
  203		if ctxErr := ctx.Err(); ctxErr != nil {
  204			return "", false, fmt.Errorf("probe symbolic ref %s: %w", refName, ctxErr)
  205		}
  206		var exitErr *exec.ExitError
  207		var stderr []byte
  208		if errors.As(err, &exitErr) {
  209			stderr = exitErr.Stderr
  210			if refLookupAbsent(err, stderr) {
  211				return "", false, nil
  212			}
  213		}
  214		detail := strings.TrimSpace(string(stderr))
  215		if detail == "" {
  216			return "", false, fmt.Errorf("probe symbolic ref %s: %w", refName, err)
  217		}
  218		return "", false, fmt.Errorf("probe symbolic ref %s: %s: %w", refName, detail, err)
  219	}
