  221	// isRefCASConflict reports that git rejected the expected old value, including
  222	// the cases where a required ref disappeared or a create-only ref appeared.
  223	func isRefCASConflict(stderr []byte) bool {
  224		msg := strings.ToLower(string(stderr))
  225		return strings.Contains(msg, "but expected") ||
  226			strings.Contains(msg, "unable to resolve reference") ||
  227			strings.Contains(msg, "reference already exists")
  228	}
