   43	// casUpdateRef adapts precise native Git CAS outcomes to the legacy retry
   44	// sentinel used by checkpoint writers.
   45	func casUpdateRef(ctx context.Context, repoRoot string, refName plumbing.ReferenceName, newHash, expectedHash plumbing.Hash) error {
   46		err := gitrepo.CompareAndSwapRef(ctx, repoRoot, refName, newHash, expectedHash)
   47		if err == nil {
   48			return nil
   49		}
   50		if errors.Is(err, gitrepo.ErrRefCASConflict) || errors.Is(err, gitrepo.ErrRefLocked) {
   51			return fmt.Errorf("%w: %w", ErrShadowRefBusy, err)
   52		}
   53		return fmt.Errorf("compare and swap ref %s: %w", refName, err)
   54	}
