   56	func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
   57		lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
   58		if err := os.MkdirAll(lockDir, 0o750); err != nil {
   59			return "", fmt.Errorf("create persistent ref lock directory: %w", err)
   60		}
   61		safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
   62		return filepath.Join(lockDir, safe+".lock"), nil
   63	}
