   68	
   69	func withPersistentRefFlockWait(
   70		ctx context.Context,
   71		commonDir string,
   72		refName plumbing.ReferenceName,
   73		wait time.Duration,
   74		fn func() error,
   75	) error {
   76		path, err := persistentRefLockPath(commonDir, refName)
   77		if err != nil {
   78			return err
   79		}
   80		acquireCtx := ctx
   81		cancel := func() {}
   82		if wait > 0 {
   83			acquireCtx, cancel = context.WithTimeout(ctx, wait)
   84		}
   85		release, err := flock.AcquireContext(acquireCtx, path)
   86		cancel()
   87		if err != nil {
   88			if wait > 0 && errors.Is(err, context.DeadlineExceeded) && ctx.Err() == nil {
   89				return fmt.Errorf("timed out waiting for persistent ref lock %s after %s: %w", refName, wait, err)
   90			}
   91			return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
   92		}
   93		defer release()
   94		return fn()
   95	}
